INSERT INTO `oc_paperwork` (`zone_id`, `state`, `b2c_stat_levy_type`, `b2c_stat_levy_liable`, `b2c_paperwork_req`, `b2c_paperwork_exem_lim`, `b2b_paperwork_inb_req`, `b2b_paperwork_outb_req`, `additional_notes`) VALUES
(1476, 'Andhra Pradesh', 'Nil', '', 'Consumer Invoice', 'Nil', 'Consumer Invoice + VAT Form x/600(online)', 'CI + VAT Form x/600(online)', 'Intra-India shipments of the commodities in exemption lists of VAT regulations of the destination state are not subject to any VAT form under B2C & B2B shipments.TIN number of shipper Consignee is mandatory on commercial invoice in case of B2B (and of shipper in case ofB2C). Fedex has suspended w-commerce B2C COD shipments to Kerala.VAT Form (wherever applicable) may be for select goods or select category of dealers. Pls visit the destination state VAT website for further information.Declaration from consignee may be required in case of B2C / C2C movements as per the destination state requirement.Gift or sample shipments to Arunachal Pradesh up to a value of INR 10,000 (declared on Invoice) are exempt from Entry Tax.Entry Tax is charged on selected commodity as listed under the destination state\'s VAT website.'),
(1475, 'Andaman & Nicobar', 'Nil', '', 'Consumer Invoice', 'Nil', 'Consumer Invoice', '', 'Intra-India shipments of the commodities in exemption lists of VAT regulations of the destination state are not subject to any VAT form under B2C & B2B shipments.TIN number of shipper Consignee is mandatory on commercial invoice in case of B2B (and of shipper in case ofB2C). Fedex has suspended w-commerce B2C COD shipments to Kerala.VAT Form (wherever applicable) may be for select goods or select category of dealers. Pls visit the destination state VAT website for further information.Declaration from consignee may be required in case of B2C / C2C movements as per the destination state requirement.Gift or sample shipments to Arunachal Pradesh up to a value of INR 10,000 (declared on Invoice) are exempt from Entry Tax.Entry Tax is charged on selected commodity as listed under the destination state\'s VAT website.'),
(1477, 'Arunachal Pradesh', 'Entry Tax', 'Consignee', 'Consumer Invoice', '<10,000', 'Consumer Invoice + RC of consignee**', '', 'Intra-India shipments of the commodities in exemption lists of VAT regulations of the destination state are not subject to any VAT form under B2C & B2B shipments.TIN number of shipper Consignee is mandatory on commercial invoice in case of B2B (and of shipper in case ofB2C). Fedex has suspended w-commerce B2C COD shipments to Kerala.VAT Form (wherever applicable) may be for select goods or select category of dealers. Pls visit the destination state VAT website for further information.Declaration from consignee may be required in case of B2C / C2C movements as per the destination state requirement.Gift or sample shipments to Arunachal Pradesh up to a value of INR 10,000 (declared on Invoice) are exempt from Entry Tax.Entry Tax is charged on selected commodity as listed under the destination state\'s VAT website.Self certified copy of Registration certificate of consignee is required to move the ship to Arunachal pardesh.'),
(1478, 'Assam', 'Entry Tax*', 'Carrier*', 'Consumer Invoice(B2C e-commerce)/From 62', 'Nil', 'Consumer Invoice + VAT Form 61(manual)', 'Consumer Invoice + VAT Form 63', 'Entry permit for e-commerce B2C shipments (Air  mode) to Assam , odisha, West Bengal & Bihar is exempted subject to payment of Entry Tax. VAT from is applicable for normal B2C,B2B & C2C shipments . Shipper will rimburse Fedex for any payments of entry tax made on its behalf. Please contact is interested in availling of the service. Entry Tax process for Asssam, odisha & Bihar under surface mode is not yet started. COD service is suspended for kerala. '),
(1479, 'Bihar', 'Entry Tax', 'Carrier*', 'Consumer Invoice+VAT From D IX(online)', '<10,000', 'Consumer Invoice +VAT From D IX for>INR 10,000(online)', 'Consumer Invoice + VAT Form D IX for>INR 10K(online)', 'Entry permit for e-commerce B2C shipments (Air  mode) to Assam , odisha, West Bengal & Bihar is exempted subject to payment of Entry Tax. VAT from is applicable for normal B2C,B2B & C2C shipments . Shipper will rimburse Fedex for any payments of entry tax made on its behalf. Please contact is interested in availling of the service. Entry Tax process for Asssam, odisha & Bihar under surface mode is not yet started. COD service is suspended for kerala. '),
